effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm) * alphac;
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 umefx;
        umefx = acScreenNorm; 
        // if(offset.x != 0.0 && offset.y != 0.0) { 
        umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
         // }

        // vec2 scaleVec;
        // scaleVec = vec2(1.0*stretch.x,1.0*stretch.y);
        // umefx /= scaleVec;

        /////////////////////////

        vec4 shadow = texture2DCv(vblur.texture,umefx);

        vec4 shadowb = (colorshadow*alpha) * shadow.a;

    	gl_FragColor = newLayer(shadowb, texColor);
    	// gl_FragColor = mix(texColor, factor, alpha);

    }
